"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["43041"],{7831(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.grupo_formulario.ocorrencias_obrigatorias","status":422,"titulo":"O grupo n\xe3o declara o m\xednimo de ocorr\xeancias ou se o candidato \xe9 uma delas"},"descricao":{"codigo":"uniplus.grupo_formulario.ocorrencias_obrigatorias","requisitos":["UNI-REQ-0146"],"oQueAconteceu":["Um grupo repet\xedvel declara quantas vezes se repete: o m\xednimo de ocorr\xeancias, se o candidato \xe9 uma delas e, opcionalmente, o m\xe1ximo (UNI-REQ-0146). O bloco `ocorrencias` do grupo n\xe3o traz `minimo` ou n\xe3o traz `incluiCandidato`, e a API n\xe3o assume valor por quem enviou, porque os dois mudam quantas ocorr\xeancias o candidato precisa informar.","A mensagem \xe9 \\"O m\xednimo de ocorr\xeancias do grupo \xe9 obrigat\xf3rio.\\" (`field` igual a `grupos[i].ocorrencias.minimo`) ou \\"\xc9 obrigat\xf3rio declarar se o candidato \xe9 uma das ocorr\xeancias do grupo.\\" (`field` igual a `grupos[i].ocorrencias.incluiCandidato`). Com o bloco `ocorrencias` ausente, saem as duas. Na cria\xe7\xe3o e na atualiza\xe7\xe3o de um modelo de formul\xe1rio o `field` come\xe7a por `conteudo.`. A recusa vem na lista `errors`, junto das demais recusas do grupo, e nada \xe9 gravado.","Na avalia\xe7\xe3o de um formul\xe1rio port\xe1vel, o bloco `ocorrencias` ausente ou nulo produz uma recusa com `field` igual a `paginas[i].grupos[j].ocorrencias`."],"comoResolver":["Envie `ocorrencias` com `minimo` (0 ou mais) e `incluiCandidato` (verdadeiro ou falso). O `maximo` \xe9 opcional: sem ele, o grupo aceita qualquer quantidade a partir do m\xednimo. Se o grupo inclui o candidato como membro, o `minimo` \xe9 ao menos 1."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio","Avalia\xe7\xe3o de um formul\xe1rio port\xe1vel"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Grupo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);